BEGIN;
DO $$ BEGIN CREATE TYPE user_role AS ENUM ('patient','caregiver'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN CREATE TYPE dose_status AS ENUM ('pending','taken','missed','skipped','snoozed'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN CREATE TYPE notification_type AS ENUM ('sos','alert','success','reminder','info'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
CREATE TABLE IF NOT EXISTS users(id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,name VARCHAR(100) NOT NULL,email VARCHAR(254) NOT NULL UNIQUE,password_hash TEXT NOT NULL,role user_role NOT NULL,invite_code VARCHAR(12) UNIQUE,snooze_minutes SMALLINT NOT NULL DEFAULT 10 CHECK(snooze_minutes BETWEEN 1 AND 60),grace_minutes SMALLINT NOT NULL DEFAULT 45 CHECK(grace_minutes BETWEEN 10 AND 240),is_active BOOLEAN NOT NULL DEFAULT TRUE,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),CHECK((role='patient' AND invite_code IS NOT NULL) OR (role='caregiver' AND invite_code IS NULL)));
CREATE TABLE IF NOT EXISTS caregiver_patient_links(id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,patient_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE,caregiver_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),UNIQUE(patient_id,caregiver_id),CHECK(patient_id<>caregiver_id));
CREATE TABLE IF NOT EXISTS medicines(id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,patient_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE,name VARCHAR(150) NOT NULL,dosage VARCHAR(100) NOT NULL DEFAULT '',instructions VARCHAR(500) NOT NULL DEFAULT '',times TIME[] NOT NULL CHECK(cardinality(times) BETWEEN 1 AND 12),stock INTEGER CHECK(stock IS NULL OR stock>=0),pills_per_dose SMALLINT NOT NULL DEFAULT 1 CHECK(pills_per_dose BETWEEN 1 AND 100),active BOOLEAN NOT NULL DEFAULT TRUE,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS doses(id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,medicine_id BIGINT NOT NULL REFERENCES medicines(id) ON DELETE CASCADE,patient_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE,dose_date DATE NOT NULL DEFAULT CURRENT_DATE,scheduled_time TIME NOT NULL,status dose_status NOT NULL DEFAULT 'pending',taken_at TIMESTAMPTZ,snooze_until TIMESTAMPTZ,reminded BOOLEAN NOT NULL DEFAULT FALSE,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),UNIQUE(medicine_id,dose_date,scheduled_time));
CREATE TABLE IF NOT EXISTS checkins(id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,patient_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE,checkin_date DATE NOT NULL DEFAULT CURRENT_DATE,mood SMALLINT NOT NULL CHECK(mood BETWEEN 1 AND 5),note VARCHAR(200) NOT NULL DEFAULT '',created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),UNIQUE(patient_id,checkin_date));
CREATE TABLE IF NOT EXISTS notifications(id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,user_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE,type notification_type NOT NULL DEFAULT 'info',text VARCHAR(1000) NOT NULL,read BOOLEAN NOT NULL DEFAULT FALSE,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE INDEX IF NOT EXISTS idx_links_caregiver ON caregiver_patient_links(caregiver_id);CREATE INDEX IF NOT EXISTS idx_medicines_patient ON medicines(patient_id,active);CREATE INDEX IF NOT EXISTS idx_doses_patient_date ON doses(patient_id,dose_date);CREATE INDEX IF NOT EXISTS idx_doses_due ON doses(dose_date,status,scheduled_time);CREATE INDEX IF NOT EXISTS idx_checkins_patient_date ON checkins(patient_id,checkin_date DESC);CREATE INDEX IF NOT EXISTS idx_notifications_user_created ON notifications(user_id,created_at DESC);CREATE INDEX IF NOT EXISTS idx_notifications_unread ON notifications(user_id) WHERE read=FALSE;
COMMIT;
